export type MailAttachment = { filename: string; content: string | Buffer; contentType?: string };

/**
 * Build the invoice attachment for an email. There is no PDF library installed
 * (and we can't add dependencies), so we attach the branded, print-ready
 * invoice HTML produced by `lib/invoices.ts` — recipients open it and use their
 * browser's Print → Save as PDF, matching the on-site download route.
 */
async function invoiceAttachment(invoiceId: string): Promise<MailAttachment | null> {
  try {
    const invoice = await db.invoice.findUnique({
      where: { id: invoiceId },
      include: { user: { select: { name: true, email: true } } },
    });
    if (!invoice) return null;
    // Use the SAME branding the dashboard and the download route use, so the
    // invoice a customer receives by email carries the identifier they can quote
    // back at you — and the seller block, which only reaches emailed invoices
    // through this path. Previously this hardcoded `#00012`-style numbering while
    // every on-screen copy showed `INV-00012`: the customer and the support agent
    // would have been reading two different invoice numbers for one invoice.
    const branding = await invoiceBranding();
    const html = renderInvoiceHTML(invoice, invoice.user, branding);
    const number = formatInvoiceNumber(invoice.number, branding.numberPrefix);
